<script setup>
import {computed,onBeforeUnmount,ref,toRaw,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {useContext} from '../composables/context.js';
import {useAccess} from '../composables/access.js';
import {api} from '../services/accounting.js';
import {reportMoney as money,reportDate as date,downloadCsv} from '../services/report-format.js';
import {errorText} from '../locales/accounting.js';
import {payrollErrors,payrollStatus} from '../locales/payroll.js';
import {decimal} from '../../../shared/money.js';
import {companyHasPayroll} from '../../../shared/payroll-agreements.js';
import {corporateAmount} from '../../../shared/corporate-tax.js';
import PayrollEmployeeForm from '../components/PayrollEmployeeForm.vue';
import PayrollEditor from '../components/PayrollEditor.vue';
import PayrollBatch from '../components/PayrollBatch.vue';
import PayrollDeleteBatch from '../components/PayrollDeleteBatch.vue';
import PayrollPosting from '../components/PayrollPosting.vue';
import PayrollPdf from '../components/PayrollPdf.vue';
import FormDialog from '../components/FormDialog.vue';
import EntryDetail from '../components/EntryDetail.vue';
import '../assets/payroll.css';
const {company,selectedExercise}=useContext(),{can}=useAccess(),route=useRoute(),router=useRouter();
const tab=ref(route.query.tab==='trabajadores'?'workers':'slips'),employees=ref([]),slips=ref([]),settings=ref(null),settingsInput=ref({contribution_account:'',notes:''}),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),search=ref(''),monthFilter=ref(''),workerForm=ref(null),batch=ref(null),deleteBatch=ref(null),editor=ref(null),posting=ref(null),pdfId=ref(null),entryId=ref(null),action=ref(null),actionReason=ref(''),actionDate=ref('');let generation=0;
const msg=cause=>payrollErrors[cause.code]||errorText(cause),matches=computed(()=>{const term=search.value.trim().toLocaleLowerCase('es-ES');return slips.value.filter(row=>(!monthFilter.value||row.period_from.startsWith(monthFilter.value))&&(!term||[row.employee_snapshot.profile.name,row.employee_snapshot.profile.code].some(value=>value.toLocaleLowerCase('es-ES').includes(term))));});
const workerRows=computed(()=>{const term=search.value.trim().toLocaleLowerCase('es-ES');return employees.value.filter(row=>!term||[row.profile.name,row.profile.code,row.profile.tax_id].some(value=>value.toLocaleLowerCase('es-ES').includes(term)));});
const summary=computed(()=>{const rows=matches.value.filter(row=>row.status==='posted'),sum=key=>decimal(rows.reduce((value,row)=>value+corporateAmount(row.calculation.totals[key]),0n));return {count:rows.length,gross:sum('gross'),net:sum('net'),cost:sum('company_cost')};});
const deletable=computed(()=>matches.value.filter(row=>row.status==='draft'));
function askBatchDelete(){deleteBatch.value={rows:deletable.value.map(row=>({id:row.id,version:row.version})),scope:company.value.name+' · '+selectedExercise.value.name+(monthFilter.value?' · Mes '+monthFilter.value:' · Todos los meses')+(search.value?' · Búsqueda: '+search.value:'')};}
async function batchDeleted(result){deleteBatch.value=null;try{await reloadRows();notice.value=result.deleted_count+' borradores eliminados. Las nóminas contabilizadas y anuladas se conservan.';}catch(cause){error.value=msg(cause);}}
async function load(){const ticket=++generation;loading.value=true;error.value='';slips.value=[];employees.value=[];settings.value=null;editor.value=null;batch.value=null;deleteBatch.value=null;workerForm.value=null;posting.value=null;pdfId.value=null;action.value=null;entryId.value=null;if(!selectedExercise.value||!companyHasPayroll(company.value)){loading.value=false;return;}try{const [people,rows,data]=await Promise.all([api('/payroll/employees'),api('/payroll/slips?exercise_id='+selectedExercise.value.id),api('/payroll/settings')]);if(ticket!==generation)return;employees.value=people;slips.value=rows;settings.value=data;settingsInput.value=structuredClone(data.payload);}catch(cause){if(ticket===generation)error.value=msg(cause);}finally{if(ticket===generation)loading.value=false;}}
async function reloadRows(){slips.value=await api('/payroll/slips?exercise_id='+selectedExercise.value.id);}
function changeTab(next){tab.value=next;search.value='';void router.replace({query:next==='workers'?{tab:'trabajadores'}:{}});}
async function saveSettings(){busy.value=true;error.value='';try{settings.value=await api('/payroll/settings',{method:'PUT',body:{version:settings.value.version,payload:settingsInput.value}});settingsInput.value=structuredClone(toRaw(settings.value.payload));notice.value='Datos de nóminas de la empresa guardados.';}catch(cause){error.value=msg(cause);}finally{busy.value=false;}}
async function workerSaved(){workerForm.value=null;employees.value=await api('/payroll/employees');notice.value='Ficha del trabajador guardada.';}
function newSlip(){if(!employees.value.length){tab.value='workers';workerForm.value={employee:null};return;}const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(new Date()),target=today>=selectedExercise.value.start_date&&today<=selectedExercise.value.end_date?today:selectedExercise.value.end_date;editor.value={slip:null,year:Number(target.slice(0,4)),month:Number(target.slice(5,7))};}
function newBatch(){const today=new Intl.DateTimeFormat('sv-SE',{timeZone:'Europe/Madrid'}).format(new Date()),target=monthFilter.value?monthFilter.value+'-01':today>=selectedExercise.value.start_date&&today<=selectedExercise.value.end_date?today:selectedExercise.value.end_date;batch.value={year:Number(target.slice(0,4)),month:Number(target.slice(5,7))};}
async function batchSaved(result){batch.value=null;changeTab('slips');monthFilter.value=result.year+'-'+String(result.month).padStart(2,'0');try{await reloadRows();notice.value=(result.replayed?'Grupo recuperado: ':'')+result.created_count+' borradores preparados. '+result.skipped_count+' trabajadores omitidos o con nómina existente.';}catch(cause){error.value=msg(cause);}}
async function openSlip(row,post=false){error.value='';try{const data=await api('/payroll/slips/'+row.id);if(post)posting.value=data;else editor.value={slip:data,year:Number(data.period_from.slice(0,4)),month:Number(data.period_from.slice(5,7))};}catch(cause){error.value=msg(cause);}}
async function saved(){editor.value=null;posting.value=null;await reloadRows();notice.value='Nómina guardada.';}
function askAction(row,kind){action.value={row,kind,request_id:crypto.randomUUID()};actionReason.value='';actionDate.value=row.period_to;}
async function confirmAction(){busy.value=true;error.value='';try{const {row,kind,request_id}=action.value;await api('/payroll/slips/'+row.id+(kind==='void'?'/void':''),{method:kind==='void'?'POST':'DELETE',body:{version:row.version,request_id,date:actionDate.value,reason:actionReason.value}});action.value=null;await reloadRows();notice.value=kind==='void'?'Nómina anulada mediante un asiento inverso.':'Borrador eliminado.';}catch(cause){error.value=msg(cause);}finally{busy.value=false;}}
function exportCsv(){const amount=value=>({amount:value}),rows=[['Nóminas',company.value.name],['Ejercicio',selectedExercise.value.name],['Estado','Desde','Hasta','Trabajador','NIF','IBAN','Tipo','Bruto','SS trabajador','IRPF','Anticipos','Otras deducciones','Líquido','SS empresa','Coste empresa']];for(const row of matches.value){const p=row.employee_snapshot.profile,t=row.calculation.totals;rows.push([payrollStatus[row.status],row.period_from,row.period_to,p.name,p.tax_id,p.iban,row.kind==='extra'?'Extra':'Mensual',...['gross','employee_ss','irpf','advance','other_deductions','net','employer_ss','company_cost'].map(key=>amount(t[key]))]);}downloadCsv('nominas-'+selectedExercise.value.name+'.csv',rows);}
watch([()=>selectedExercise.value?.id,()=>company.value?.payroll_agreement],()=>void load(),{immediate:true});onBeforeUnmount(()=>generation++);
</script>
<template><div class="payroll-page"><div class="page-heading"><div><p class="eyebrow">{{ company?.name }}</p><h1>Nóminas</h1><p class="muted">{{ settings?.agreement?.label }} · Régimen general · {{ selectedExercise?.name }}</p></div><div class="actions"><button class="button" :disabled="loading||!matches.length" @click="exportCsv">Descargar resumen CSV</button><button v-if="can('accounting_write')" class="button" :disabled="loading||!employees.length||!selectedExercise||selectedExercise.status!=='open'" @click="newBatch">Crear todas las nóminas</button><button v-if="can('accounting_write')" class="button primary" :disabled="loading||!selectedExercise||selectedExercise.status!=='open'" @click="newSlip">Nueva nómina</button></div></div><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><p v-if="notice" class="notice success-note" role="status">{{ notice }}</p><p v-if="loading" role="status">Cargando nóminas…</p><p v-if="!selectedExercise" class="notice">Selecciona un ejercicio para gestionar las nóminas.</p><template v-if="settings"><details class="panel payroll-settings" :open="!settings.payload.contribution_account"><summary><strong>Datos de la empresa para nóminas</strong></summary><p class="payroll-help">{{ settings.company.name }} · NIF {{ settings.company.tax_id||'pendiente' }}. Los datos fiscales se mantienen en Empresas.</p><form class="payroll-fields" @submit.prevent="saveSettings"><label>Código cuenta cotización de la empresa<input v-model="settingsInput.contribution_account" maxlength="20" aria-label="Cuenta de cotización empresa" placeholder="11 dígitos" :disabled="!can('accounting_write')||busy" /></label><label>Notas<input v-model="settingsInput.notes" maxlength="1000" :disabled="!can('accounting_write')||busy" /></label><button v-if="can('accounting_write')" class="button" :disabled="busy">Guardar datos de nóminas</button></form></details><nav class="payroll-tabs" aria-label="Apartados de nóminas"><button class="button" :class="{primary:tab==='slips'}" @click="changeTab('slips')">Nóminas del ejercicio</button><button class="button" :class="{primary:tab==='workers'}" @click="changeTab('workers')">Trabajadores</button></nav><div class="payroll-toolbar"><label>Buscar<input v-model="search" type="search" placeholder="Nombre, código o NIF" /></label><label v-if="tab==='slips'">Mes<input v-model="monthFilter" type="month" /></label><button v-if="tab==='workers'&&can('accounting_write')" class="button" @click="workerForm={employee:null}">Nuevo trabajador</button><button class="button" :disabled="loading" @click="load">Actualizar nóminas</button><button v-if="tab==='slips'&&can('accounting_write')" class="button" :disabled="loading||busy||!deletable.length||selectedExercise?.status!=='open'" @click="askBatchDelete">Eliminar todos los borradores</button></div><template v-if="tab==='workers'"><section class="panel table-wrap"><table><thead><tr><th>Código</th><th>Trabajador / NIF</th><th>Puesto</th><th>Salario base</th><th>Alta / estado</th><th></th></tr></thead><tbody><tr v-for="row in workerRows" :key="row.id"><td>{{ row.profile.code }}</td><td>{{ row.profile.name }}<small>{{ row.profile.tax_id }}</small></td><td>{{ row.profile.job_title }}</td><td class="amount">{{ money(row.profile.base_salary) }} €/{{ row.profile.salary_unit==='daily'?'día':'mes' }}</td><td>{{ date(row.profile.employment_start) }}<small>{{ row.profile.active?'Activo':'Inactivo' }}</small><small v-if="!row.profile.agreement_reviewed">Condiciones pendientes de revisar</small></td><td><button v-if="can('accounting_write')" class="button small" @click="workerForm={employee:row}">Editar trabajador</button></td></tr><tr v-if="!workerRows.length"><td colspan="6">Añade la ficha del primer trabajador para preparar sus nóminas.</td></tr></tbody></table></section></template><template v-else><div class="payroll-totals"><div><small>Nóminas contabilizadas</small><strong>{{ summary.count }}</strong></div><div><small>Bruto contabilizado</small><strong>{{ money(summary.gross) }} €</strong></div><div><small>Líquido a percibir</small><strong>{{ money(summary.net) }} €</strong></div><div><small>Coste empresa contabilizado</small><strong>{{ money(summary.cost) }} €</strong></div></div><p class="payroll-help">Los totales excluyen borradores y nóminas anuladas. Contabilizar registra la deuda salarial; el pago bancario y las presentaciones a AEAT y Seguridad Social se realizan por separado.</p><section class="panel table-wrap"><table><thead><tr><th>Período / tipo</th><th>Trabajador</th><th>Estado</th><th class="amount">Bruto</th><th class="amount">Líquido</th><th class="amount">Coste empresa</th><th></th></tr></thead><tbody><tr v-for="row in matches" :key="row.id" :data-payroll-id="row.id"><td>{{ date(row.period_from) }} — {{ date(row.period_to) }}<small>{{ row.kind==='extra'?'Paga extraordinaria':'Mensual' }}</small></td><td>{{ row.employee_snapshot.profile.name }}<small>{{ row.employee_snapshot.profile.code }}</small></td><td>{{ payrollStatus[row.status] }}<small v-if="row.status==='draft'&&!row.calculation.ready">Pendiente de revisión</small></td><td class="amount">{{ money(row.calculation.totals.gross) }}</td><td class="amount">{{ money(row.calculation.totals.net) }}</td><td class="amount">{{ money(row.calculation.totals.company_cost) }}</td><td><div class="actions"><button class="button small" @click="openSlip(row)">{{ row.status==='draft'&&can('accounting_write')?'Editar nómina':'Consultar nómina' }}</button><button class="button small" @click="pdfId=row.id">Ver PDF nómina</button><button v-if="row.entry_id" class="button small" @click="entryId=row.entry_id">Ver asiento</button><template v-if="can('accounting_write')&&selectedExercise.status==='open'"><button v-if="row.status==='draft'" class="button small" :disabled="!row.calculation.ready" @click="openSlip(row,true)">Contabilizar nómina</button><button v-if="row.status==='posted'" class="button small" @click="askAction(row,'void')">Anular nómina</button><button v-if="row.status==='draft'" class="button small" @click="askAction(row,'delete')">Eliminar borrador</button></template></div></td></tr><tr v-if="!matches.length"><td colspan="7">No hay nóminas en este ejercicio o filtro.</td></tr></tbody></table></section></template></template><PayrollEmployeeForm v-if="workerForm" :employee="workerForm.employee" :agreement="settings.agreement" :default-code="'TRAB-'+String(employees.length+1).padStart(3,'0')" @close="workerForm=null" @saved="workerSaved" /><PayrollBatch v-if="batch" :employees="employees" :exercise-id="selectedExercise.id" :year="batch.year" :month="batch.month" @close="batch=null" @saved="batchSaved" /><PayrollDeleteBatch v-if="deleteBatch" :rows="deleteBatch.rows" :scope="deleteBatch.scope" :exercise-id="selectedExercise.id" @close="deleteBatch=null" @saved="batchDeleted" /><PayrollEditor v-if="editor" :slip="editor.slip" :employees="employees" :year="editor.year" :month="editor.month" :exercise-id="selectedExercise.id" @close="editor=null" @saved="saved" /><PayrollPosting v-if="posting" :slip="posting" @close="posting=null" @saved="saved" /><PayrollPdf v-if="pdfId" :slip-id="pdfId" @close="pdfId=null" /><EntryDetail v-if="entryId" :entry-id="entryId" @close="entryId=null" /><FormDialog v-if="action" :title="action.kind==='void'?'Anular nómina con asiento inverso':'Eliminar borrador de nómina'" :busy="busy" @close="action=null"><form class="payroll-form" @submit.prevent="confirmAction"><p>{{ action.row.employee_snapshot.profile.name }} · {{ date(action.row.period_from) }}. {{ action.kind==='void'?'Se conservará la nómina y se generará un asiento inverso.':'Se eliminará el borrador sin movimientos contables.' }}</p><p v-if="error" class="notice error-notice" role="alert">{{ error }}</p><template v-if="action.kind==='void'"><label>Fecha del asiento inverso<input v-model="actionDate" type="date" required /></label><label>Motivo<input v-model="actionReason" maxlength="200" required /></label></template><div class="dialog-actions"><button type="button" class="button" :disabled="busy" @click="action=null">Cancelar</button><button class="button primary" :disabled="busy">{{ action.kind==='void'?'Confirmar anulación':'Confirmar eliminación' }}</button></div></form></FormDialog></div></template>
